<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Download, Plus, SlidersHorizontal, TrendingUp, ArrowUpDown } from 'lucide-vue-next';
import { studio, contentMetrics } from '@/services/studio';
import { downloadFile } from '@/services/storage';
import DataChart from '@/components/DataChart.vue';
import { Dialog, DialogContent, DialogTitle, DialogDescription } from '@/components/ui';
import type { PlatformContent, ContentAttributes } from '@/types/studio';
import { toast } from 'vue-sonner';
const props=defineProps<{projectId:string}>();const route=useRoute();const router=useRouter();
const tab=computed(()=>['overview','content','insights'].includes(String(route.query.report))?String(route.query.report):'overview');
const days=ref(Number(route.query.days)||7);const cumulative=ref(route.query.metric!=='increment');const search=ref('');const accountId=ref('all');const kind=ref('all');const theme=ref('all');const collection=ref('all');const sort=ref('publishedAt');const descending=ref(true);const page=ref(1);const columns=ref(['views','likes','comments','shares']);const showColumns=ref(false);const externalOpen=ref(false);const externalIds=ref<string[]>([]);const detailId=ref('');const attributes=ref<ContentAttributes|null>(null);const dimension=ref<keyof ContentAttributes>('hook');
const metrics=[{key:'views',label:'播放量'},{key:'likes',label:'点赞'},{key:'comments',label:'评论'},{key:'shares',label:'分享'}] as const;
const content=computed(()=>studio.value.content.filter(c=>c.projectIds.includes(props.projectId)));
const themes=computed(()=>[...new Set(content.value.map(c=>c.attributes.theme))]);
const rows=computed(()=>content.value.filter(c=>(accountId.value==='all'||c.accountId===accountId.value)&&(kind.value==='all'||c.type===kind.value)&&(theme.value==='all'||c.attributes.theme===theme.value)&&(collection.value==='all'||c.collection===collection.value)&&`${c.title} ${studio.value.accounts.find(a=>a.id===c.accountId)?.handle??''}`.toLowerCase().includes(search.value.toLowerCase())).map(c=>({content:c,...contentMetrics(c,days.value,cumulative.value)})).sort((a,b)=>{const key=sort.value;const x=key==='publishedAt'?a.content.publishedAt:a.metrics?.[key as 'views']??-1;const y=key==='publishedAt'?b.content.publishedAt:b.metrics?.[key as 'views']??-1;return (x<y?-1:x>y?1:0)*(descending.value?-1:1);}));
const available=computed(()=>rows.value.filter(r=>r.metrics));const totals=computed(()=>metrics.map(m=>({label:m.label,value:available.value.reduce((n,r)=>n+(r.metrics?.[m.key]??0),0)})));
const detail=computed(()=>studio.value.content.find(c=>c.id===detailId.value));
const external=computed(()=>studio.value.content.filter(c=>!c.projectIds.includes(props.projectId)&&studio.value.accounts.some(a=>!a.deleted&&a.id===c.accountId&&a.status==='已授权')));
const chart=computed(()=>Array.from({length:days.value},(_,i)=>{const date=new Date(Date.now()-(days.value-i-1)*86400000).toISOString().slice(0,10);let value=0;let included=0;for(const {content:c} of available.value){const snap=c.snapshots.find(s=>s.date===date);if(snap){const previous=c.snapshots.filter(s=>s.date<date).at(-1);if(cumulative.value){value+=snap.views;included++;}else if(previous){value+=snap.views-previous.views;included++;}}}return {day:date.slice(5),'播放量':included?value:'',};}));
const accountRows=computed(()=>[...new Set(rows.value.map(r=>r.content.accountId))].map(id=>({id,name:studio.value.accounts.find(a=>a.id===id)?.handle??'已移除帐号',count:rows.value.filter(r=>r.content.accountId===id).length,views:available.value.filter(r=>r.content.accountId===id).reduce((n,r)=>n+(r.metrics?.views??0),0)})));
const insights=computed(()=>[...new Set(rows.value.map(r=>String(r.content.attributes[dimension.value])))].map(name=>{const list=available.value.filter(r=>String(r.content.attributes[dimension.value])===name);const views=list.map(r=>r.metrics!.views).sort((a,b)=>a-b);const mid=Math.floor(views.length/2);const median=views.length?(views.length%2?views[mid]!:(views[mid-1]!+views[mid]!)/2):null;const interactions=list.reduce((n,r)=>n+r.metrics!.likes+r.metrics!.comments+r.metrics!.shares,0);return {name,count:list.length,median,interactions,first:list[0]?.content};}));
watch([search,accountId,kind,theme,collection,sort,descending,days,cumulative],()=>{page.value=1;});
watch([days,cumulative],()=>{void router.replace({query:{...route.query,days:String(days.value),metric:cumulative.value?'total':'increment'}});});
watch(()=>route.query, q=>{if(q.days&&[7,30,90].includes(Number(q.days)))days.value=Number(q.days);if(q.metric)cumulative.value=q.metric!=='increment';});
function showDetail(c:PlatformContent){detailId.value=c.id;attributes.value={...c.attributes};}
function associate(){for(const id of externalIds.value){const c=studio.value.content.find(c=>c.id===id);if(c&&!c.projectIds.includes(props.projectId))c.projectIds.push(props.projectId);}externalOpen.value=false;externalIds.value=[];toast.success('已关联到当前项目');}
function csv(){const cells=(v:unknown)=>{const text=String(v??'');return '"'+(/^[=+\-@\t\r]/.test(text)?"'":'')+text.replace(/"/g,'""')+'"';};const header=['标题','帐号','类型','发布时间',...metrics.map(m=>m.label),'主题','产品类型','Hook','场景','形式','属性确认','数据状态','统计口径','时间范围','数据来源','更新时间','收藏','完播率','3秒留存','5秒留存'];const data=rows.value.map(r=>[r.content.title,studio.value.accounts.find(a=>a.id===r.content.accountId)?.handle,r.content.type,r.content.publishedAt,...metrics.map(m=>r.metrics?.[m.key]??r.reason),r.content.attributes.theme,r.content.attributes.product,r.content.attributes.hook,r.content.attributes.scene,r.content.attributes.format,r.content.attributes.confirmed?'已确认':'AI 建议',r.reason||'可用',cumulative.value?'累计':'区间增量',`近 ${days.value} 天`,'模拟平台内容快照',r.content.snapshots.at(-1)?.date,'接口能力未验证',r.content.type==='图文'?'不适用':'接口能力未验证','接口能力未验证','接口能力未验证']);downloadFile('项目内容分析.csv',new Blob(['\ufeff'+[header,...data].map(row=>row.map(cells).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));}
function recreate(c:PlatformContent){const reference={id:`content-${c.id}`,url:'',title:c.title,author:studio.value.accounts.find(a=>a.id===c.accountId)?.handle??'',duration:'00:15',source:'项目优质内容'};if(!studio.value.references.some(r=>r.id===reference.id))studio.value.references.push(reference);void router.push({query:{section:'gen',mode:'expert',reference:reference.id}});}
function collect(){const bad=content.value.filter(c=>c.collection==='采集失败');bad.forEach(c=>{if(studio.value.accounts.find(a=>a.id===c.accountId)?.status==='已授权')c.collection='可用';});toast.success('演示采集完成；不会补造缺失的历史快照');}
</script>
<template><div class="space-y-5"><div class="flex flex-wrap items-center justify-between gap-3"><nav class="flex gap-1"><button v-for="t in [{key:'overview',label:'总览'},{key:'content',label:'内容明细'},{key:'insights',label:'内容洞察'}]" :key="t.key" class="studio-tab" :class="tab===t.key&&'studio-active'" @click="router.push({query:{...route.query,report:t.key}})">{{t.label}}</button></nav><div class="flex gap-2"><button class="studio-btn" @click="externalOpen=true"><Plus class="h-4 w-4" />关联历史内容</button><button class="studio-btn" @click="collect">采集数据</button><button class="studio-primary" @click="csv"><Download class="h-4 w-4" />导出 CSV</button></div></div><div class="flex flex-wrap gap-3"><input v-model="search" class="studio-field !w-52" placeholder="搜索内容、帐号"><select v-model="accountId" class="studio-field !w-40" aria-label="分析帐号"><option value="all">全部帐号</option><option v-for="a in studio.accounts" :key="a.id" :value="a.id">{{a.name}}</option></select><select v-model="kind" class="studio-field !w-28"><option value="all">全部类型</option><option>视频</option><option>图文</option></select><select v-model="theme" class="studio-field !w-36"><option value="all">全部主题</option><option v-for="t in themes" :key="t">{{t}}</option></select><select v-model="days" class="studio-field !w-28"><option :value="7">近 7 天</option><option :value="30">近 30 天</option><option :value="90">近 90 天</option></select><select v-model="cumulative" class="studio-field !w-32"><option :value="true">累计数据</option><option :value="false">区间增量</option></select></div><div class="flex justify-between rounded-xl bg-sky-50 px-4 py-3 text-[11px] leading-5 text-sky-700"><span>当前范围 {{rows.length}} 条内容，可用 {{available.length}} 条 · {{cumulative?'累计截至最近快照；趋势按近 '+days+' 天展示':'区间增量需要完整历史快照'}} · 最新快照 {{rows.map(r=>r.content.snapshots.at(-1)?.date??'').sort().at(-1)||'暂无'}}</span><span>演示数据</span></div>
<template v-if="tab==='overview'"><div class="grid grid-cols-5 gap-3"><div class="studio-card"><p class="text-xs text-slate-400">项目已发布内容</p><p class="mt-3 text-2xl font-semibold">{{rows.length}}</p></div><div v-for="m in totals" :key="m.label" class="studio-card"><p class="text-xs text-slate-400">{{m.label}}</p><p class="mt-3 text-2xl font-semibold">{{available.length?m.value.toLocaleString():'—'}}</p></div></div><div class="studio-card"><div class="mb-5 flex justify-between"><h2 class="text-sm font-semibold">播放趋势</h2><span class="text-xs text-slate-400">{{cumulative?'累计快照':'每日增量'}} · 缺失日期留空</span></div><DataChart type="area" :data="chart" :series="[{name:'播放量',color:'#11a3fd',type:'area'}]" /></div><div class="studio-card"><h2 class="mb-4 text-sm font-semibold">帐号表现</h2><table class="studio-table"><thead><tr><th>帐号</th><th>内容数</th><th>可用播放量</th></tr></thead><tbody><tr v-for="a in accountRows" :key="a.id"><td>{{a.name}}</td><td>{{a.count}}</td><td>{{a.views.toLocaleString()}}</td></tr></tbody></table><p v-if="!accountRows.length" class="py-8 text-center text-sm text-slate-400">发布内容后，在这里查看帐号表现</p></div></template>
<template v-else-if="tab==='content'"><div class="flex items-center gap-3"><select v-model="collection" class="studio-field !w-36"><option value="all">全部数据状态</option><option>可用</option><option>无权限</option><option>采集失败</option><option>未采集</option></select><select v-model="sort" class="studio-field !w-36"><option value="publishedAt">按发布时间</option><option v-for="m in metrics" :key="m.key" :value="m.key">按{{m.label}}</option></select><button class="studio-btn" aria-label="切换排序" @click="descending=!descending"><ArrowUpDown class="h-4 w-4" />{{descending?'降序':'升序'}}</button><button class="studio-btn ml-auto" @click="showColumns=!showColumns"><SlidersHorizontal class="h-4 w-4" />显示列</button></div><div v-if="showColumns" class="flex gap-5 rounded-xl bg-slate-50 p-3 text-xs"><label v-for="m in metrics" :key="m.key"><input v-model="columns" type="checkbox" :value="m.key">{{m.label}}</label></div><div class="overflow-auto rounded-2xl border border-slate-200"><table class="studio-table"><thead><tr><th>内容 / 帐号</th><th v-for="m in metrics.filter(m=>columns.includes(m.key))" :key="m.key">{{m.label}}</th><th>内容属性</th><th>发布时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows.slice((page-1)*8,page*8)" :key="r.content.id"><td><button class="max-w-56 truncate text-left font-medium text-slate-800" @click="showDetail(r.content)">{{r.content.title}}</button><p class="mt-1 text-[11px] text-slate-400">{{studio.accounts.find(a=>a.id===r.content.accountId)?.handle}} · {{r.content.type}}</p></td><td v-for="m in metrics.filter(m=>columns.includes(m.key))" :key="m.key">{{r.metrics?.[m.key]?.toLocaleString()??r.reason}}</td><td><span class="studio-badge">{{r.content.attributes.hook}}</span><p class="mt-1 text-[10px] text-slate-400">{{r.content.attributes.confirmed?'人工已确认':'AI 建议待确认'}}</p></td><td>{{new Date(r.content.publishedAt).toLocaleDateString()}}</td><td><button class="whitespace-nowrap text-sky-600" @click="showDetail(r.content)">查看详情</button></td></tr></tbody></table><p v-if="!rows.length" class="py-16 text-center text-sm text-slate-400">暂无符合条件的内容，可关联帐号历史内容</p></div><div class="flex items-center justify-end gap-3 text-xs text-slate-400"><span>共 {{rows.length}} 条 · {{page}} / {{Math.max(1,Math.ceil(rows.length/8))}}</span><button class="studio-btn" :disabled="page===1" @click="page--">上一页</button><button class="studio-btn" :disabled="page*8>=rows.length" @click="page++">下一页</button></div></template>
<template v-else><div class="flex items-center gap-3"><TrendingUp class="h-4 w-4 text-sky-500" /><span class="text-xs text-slate-500">按内容属性比较</span><select v-model="dimension" class="studio-field !w-40"><option value="hook">Hook 类型</option><option value="theme">视频主题</option><option value="product">产品类型</option><option value="scene">场景</option><option value="format">内容形式</option></select></div><div class="grid grid-cols-2 gap-4 xl:grid-cols-3"><article v-for="i in insights" :key="i.name" class="studio-card"><span class="studio-badge !bg-sky-50 !text-sky-600">{{i.name}}</span><div class="my-5 grid grid-cols-2 gap-4"><div><p class="text-[11px] text-slate-400">播放中位数</p><p class="mt-2 text-xl font-semibold">{{i.median?.toLocaleString()??'—'}}</p></div><div><p class="text-[11px] text-slate-400">互动总量</p><p class="mt-2 text-xl font-semibold">{{i.interactions.toLocaleString()}}</p></div></div><p class="text-[11px] text-slate-400">有效样本 {{i.count}} 条 · 仅为描述性统计，不作因果判断</p><button v-if="i.first" class="mt-4 text-xs text-sky-600" @click="recreate(i.first)">参考此类内容，开始新创作 →</button></article></div><p v-if="!insights.length" class="py-16 text-center text-sm text-slate-400">内容积累后，在这里比较不同创意的表现</p></template>
<p class="text-[11px] leading-6 text-slate-400">基础数据为演示快照；收藏、完播率、3 秒与 5 秒留存的接口能力未验证，不生成估算数值。发布授权不代表已取得数据读取权限。</p></div>
<Dialog :open="externalOpen" @update:open="externalOpen=$event"><DialogContent class="max-h-[80vh] max-w-2xl overflow-y-auto bg-white p-6"><DialogTitle>关联帐号历史内容</DialogTitle><DialogDescription>仅列出当前授权有效帐号的可读演示内容。关联不改变平台内容，同一内容在本项目只计一次。</DialogDescription><label v-for="c in external" :key="c.id" class="flex items-center gap-3 border-b py-4 text-sm"><input v-model="externalIds" type="checkbox" :value="c.id"><span class="flex-1">{{c.title}}<small class="mt-1 block text-slate-400">{{studio.accounts.find(a=>a.id===c.accountId)?.handle}} · {{c.type}}</small></span><span class="studio-badge">{{c.collection}}</span></label><p v-if="!external.length" class="py-8 text-sm text-slate-400">暂无可关联内容；可使用演示帐号体验历史内容。</p><button class="studio-primary" :disabled="!externalIds.length" @click="associate">关联 {{externalIds.length}} 条内容</button></DialogContent></Dialog>
<Dialog :open="!!detail" @update:open="!$event&&(detailId='')"><DialogContent class="max-h-[90vh] max-w-2xl overflow-y-auto bg-white p-6"><DialogTitle>{{detail?.title}}</DialogTitle><DialogDescription>内容属性与数据可用条件</DialogDescription><template v-if="detail&&attributes"><div class="grid grid-cols-2 gap-3"><label v-for="field in ([['theme','视频主题'],['product','产品类型'],['hook','Hook 类型'],['scene','场景'],['format','内容形式']] as const)" :key="field[0]"><span class="studio-label">{{field[1]}}</span><input v-model="attributes[field[0]]" class="studio-field"></label></div><p class="text-xs text-slate-400">{{attributes.confirmed?'人工已确认':'AI 建议，等待人工确认'}}</p><div class="flex gap-3"><button class="studio-btn" @click="attributes={...attributes,hook:'对比实测',scene:'产品使用场景',confirmed:false}">生成 AI 属性建议</button><button class="studio-primary" @click="detail.attributes={...attributes,confirmed:true};attributes.confirmed=true;toast.success('内容属性已确认保存')">确认并保存属性</button></div><div class="rounded-xl bg-slate-50 p-4 text-xs leading-7 text-slate-500">收藏：采集能力未验证<br>完播率：{{detail.type==='图文'?'图文不适用':'采集能力未验证'}}<br>3 秒 / 5 秒留存：采集能力未验证<br>来源：演示平台快照 · {{detail.collection}}<br>最近采集：{{detail.snapshots.at(-1)?.date??'未采集'}}</div><div class="flex justify-between"><button class="text-xs text-sky-600" @click="recreate(detail)">以此内容开始新创作 →</button><button v-if="!detail.filmId" class="text-xs text-slate-400" @click="detail.projectIds=detail.projectIds.filter(id=>id!==projectId);detailId=''">取消项目关联</button></div></template></DialogContent></Dialog>

</template>
